//! Generates SIDOU's checked-in C tables in `core/sid/gen/` from reSIDfp (test-only, never
//! linked into firmware). The tables are data derived from reSIDfp, so the generated files
//! carry its licence (GPL-2.0-or-later) and its authors.
//!
//! `cargo run --release -p sidou-tablegen` (from `host/`) rewrites them; the drift test
//! fails when the checked-in files differ from what this produces.

use std::fmt::Write;
use std::path::{Path, PathBuf};

use residfp_sys::{pulldown_table, CombinedWaveforms, Model, PULLDOWN_ROWS};

/// The libresidfp revision the tables come from (the third_party/libresidfp submodule).
pub const RESIDFP_REV: &str = "c1791383";

/// One generated file: its path relative to the repository root, and its contents.
pub struct Generated {
    pub path: &'static str,
    pub contents: String,
}

/// The repository root, from this crate's manifest directory.
pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .canonicalize()
        .expect("repository root")
}

/// Packs 12-bit entries two to three bytes: e0 low 8 bits; e0 high 4 | e1 low 4 << 4;
/// e1 high 8 bits.
fn pack12(row: &[u16; 4096]) -> Vec<u8> {
    row.chunks(2)
        .flat_map(|p| {
            let (a, b) = (p[0], p[1]);
            assert!(a < 0x1000 && b < 0x1000);
            [
                (a & 0xff) as u8,
                ((a >> 8) | ((b & 0x0f) << 4)) as u8,
                (b >> 4) as u8,
            ]
        })
        .collect()
}

/// The combined-waveform profiles: reSIDfp's three sampled chips, in the order of the
/// C enum in gen/grid.h. AVERAGE is reSIDfp's default and the only one compiled unless
/// SIDOU_ALL_COMBINED_PROFILES is defined.
pub const PROFILES: [(CombinedWaveforms, &str); 3] = [
    (CombinedWaveforms::Weak, "WEAK"),
    (CombinedWaveforms::Average, "AVERAGE"),
    (CombinedWaveforms::Strong, "STRONG"),
];

/// Bytes of one profile's packed table for one model.
pub const PROFILE_BYTES: usize = 5 * 6144;

fn wave_header(model: Model) -> Generated {
    let (name, guard, path, sampled) = match model {
        Model::Mos6581 => (
            "6581",
            "SIDOU_GEN_WAVE_6581_H",
            "core/sid/gen/wave_6581.h",
            "MOS6581",
        ),
        Model::Csg8580 => (
            "8580",
            "SIDOU_GEN_WAVE_8580_H",
            "core/sid/gen/wave_8580.h",
            "CSG8580",
        ),
    };
    let mut s = String::new();
    // REUSE-IgnoreStart
    s.push_str(
        "// SPDX-FileCopyrightText: 2011-2026 Leandro Nini <drfiemost@users.sourceforge.net>\n\
         // SPDX-FileCopyrightText: 2007-2010 Antti Lankila\n\
         // SPDX-License-Identifier: GPL-2.0-or-later\n",
    );
    // REUSE-IgnoreEnd
    writeln!(
        s,
        "/* Generated by sidou-tablegen; do not edit. To regenerate, from host/:\n\
         \x20*   cargo run --release -p sidou-tablegen\n\
         \x20* Source: reSIDfp (libresidfp {RESIDFP_REV}),\n\
         \x20* WaveformCalculator::buildPulldownTable({sampled}, profile): the combined-waveform\n\
         \x20* pulldown, which maps a 12-bit waveform output (the AND of the selected\n\
         \x20* waveforms) to what the chip outputs. One table per compiled profile\n\
         \x20* (gen/grid.h), each with rows in reSIDfp's order: {}.\n\
         \x20* Each row packs 4096 12-bit entries into 6144 bytes, two entries per three\n\
         \x20* bytes; sid_pulldown() in sid_osc.h unpacks them. {} bytes per profile. */",
        PULLDOWN_ROWS.join(", "),
        PROFILE_BYTES
    )
    .unwrap();
    writeln!(
        s,
        "#ifndef {guard}\n#define {guard}\n\n#include <stdint.h>\n\n#include \"grid.h\"\n"
    )
    .unwrap();
    writeln!(
        s,
        "static const uint8_t SID_PULLDOWN_{name}[SID_COMBINED_TABLES][5][6144] = {{"
    )
    .unwrap();
    for (cws, label) in PROFILES {
        let optional = cws != CombinedWaveforms::Average;
        if optional {
            writeln!(s, "#ifdef SIDOU_ALL_COMBINED_PROFILES").unwrap();
        }
        let table = pulldown_table(model, cws);
        writeln!(s, "    /* {label} */ {{").unwrap();
        for (row, row_label) in table.iter().zip(PULLDOWN_ROWS) {
            writeln!(s, "        /* {row_label} */ {{").unwrap();
            for line in pack12(row).chunks(14) {
                let bytes: Vec<String> = line.iter().map(|b| format!("0x{b:02x}")).collect();
                writeln!(s, "            {},", bytes.join(", ")).unwrap();
            }
            writeln!(s, "        }},").unwrap();
        }
        writeln!(s, "    }},").unwrap();
        if optional {
            writeln!(s, "#endif").unwrap();
        }
    }
    writeln!(s, "}};\n\n#endif").unwrap();
    Generated { path, contents: s }
}

fn grid_header() -> Generated {
    let mut s = String::new();
    // REUSE-IgnoreStart
    s.push_str(
        "// SPDX-FileCopyrightText: 2026 SIDOU contributors\n\
         // SPDX-License-Identifier: GPL-3.0-or-later\n",
    );
    // REUSE-IgnoreEnd
    let names: Vec<&str> = PROFILES.iter().map(|p| p.1).collect();
    writeln!(
        s,
        "/* Generated by sidou-tablegen; do not edit. Which generated tables are compiled.\n\
         \x20*\n\
         \x20* Combined-waveform profiles: reSIDfp's {} sampled chips. Only\n\
         \x20* AVERAGE, reSIDfp's default, is compiled ({} bytes per model) unless\n\
         \x20* SIDOU_ALL_COMBINED_PROFILES is defined (all three, {} bytes per model). */\n\
         #ifndef SIDOU_GEN_GRID_H\n#define SIDOU_GEN_GRID_H\n",
        names.join(", "),
        PROFILE_BYTES,
        PROFILE_BYTES * PROFILES.len()
    )
    .unwrap();
    let enumerators: Vec<String> = names.iter().map(|n| format!("SID_PROFILE_{n}")).collect();
    writeln!(s, "enum {{ {}, SID_PROFILES }};\n", enumerators.join(", ")).unwrap();
    writeln!(
        s,
        "/* The table index of a profile; a profile not compiled in gets AVERAGE's. */\n\
         #ifdef SIDOU_ALL_COMBINED_PROFILES\n\
         #define SID_COMBINED_TABLES {}\n\
         #define SID_COMBINED_TABLE(profile) (profile)\n\
         #else\n\
         #define SID_COMBINED_TABLES 1\n\
         #define SID_COMBINED_TABLE(profile) 0\n\
         #endif\n\n#endif",
        PROFILES.len()
    )
    .unwrap();
    Generated {
        path: "core/sid/gen/grid.h",
        contents: s,
    }
}

/// One plain shift of the noise register (reSIDfp's order, no TEST): up one, the new
/// bit 22 = bit 0 ^ bit 5.
fn noise_shift(sr: u32) -> u32 {
    (sr >> 1) | (((sr ^ (sr >> 5)) & 1) << 22)
}

/// The 2^k-shift maps of the noise register for k = 0..22, as GF(2) matrices: column i
/// is where bit i ends up. Our own derivation from the shift, no reSIDfp data.
fn noise_jump_header() -> Generated {
    let mut cols: Vec<u32> = (0..23).map(|i| noise_shift(1 << i)).collect();
    let mut s = String::new();
    // REUSE-IgnoreStart
    s.push_str(
        "// SPDX-FileCopyrightText: 2026 SIDOU contributors\n\
         // SPDX-License-Identifier: GPL-3.0-or-later\n",
    );
    // REUSE-IgnoreEnd
    s.push_str(
        "/* Generated by sidou-tablegen; do not edit. To regenerate, from host/:\n\
         \x20*   cargo run --release -p sidou-tablegen\n\
         \x20* The noise register's shift applied 2^k times, k = 0..22, as GF(2) matrices:\n\
         \x20* SID_NOISE_JUMP[k][i] is the register after 2^k shifts of bit i alone, so the\n\
         \x20* register after 2^k shifts is the XOR of the columns of its set bits\n\
         \x20* (sid_noise_jump in sid_osc.h). */\n\
         #ifndef SIDOU_GEN_NOISE_JUMP_H\n#define SIDOU_GEN_NOISE_JUMP_H\n\n#include <stdint.h>\n\n\
         static const uint32_t SID_NOISE_JUMP[23][23] = {\n",
    );
    for _ in 0..23 {
        let line: Vec<String> = cols.iter().map(|c| format!("0x{c:06x}")).collect();
        for chunk in line.chunks(8) {
            if chunk.as_ptr() == line.as_ptr() {
                s.push_str("    {");
            } else {
                s.push_str("     ");
            }
            s.push_str(&chunk.join(", "));
            s.push_str(",\n");
        }
        s.truncate(s.len() - 2);
        s.push_str("},\n");
        // Square: apply the map to each column again.
        let apply = |m: &[u32], v: u32| -> u32 {
            (0..23)
                .filter(|i| v >> i & 1 != 0)
                .fold(0, |acc, i| acc ^ m[i])
        };
        cols = cols.iter().map(|&c| apply(&cols, c)).collect();
    }
    s.push_str("};\n\n#endif\n");
    Generated {
        path: "core/sid/gen/noise_jump.h",
        contents: s,
    }
}

/// Every generated file.
pub fn generate() -> Vec<Generated> {
    vec![
        grid_header(),
        noise_jump_header(),
        wave_header(Model::Mos6581),
        wave_header(Model::Csg8580),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pack12_round_trips() {
        let mut row = [0u16; 4096];
        for (i, r) in row.iter_mut().enumerate() {
            *r = ((i * 2654435761) >> 7) as u16 & 0xfff;
        }
        let p = pack12(&row);
        assert_eq!(p.len(), 6144);
        for (i, &v) in row.iter().enumerate() {
            let b = &p[(i / 2) * 3..];
            let got = if i % 2 == 0 {
                u16::from(b[0]) | (u16::from(b[1] & 0x0f) << 8)
            } else {
                u16::from(b[1] >> 4) | (u16::from(b[2]) << 4)
            };
            assert_eq!(got, v, "entry {i}");
        }
    }
}
